 styles={'clean':('Clean BC | filter off','#263238','o','--'),'old':('Old DVAC | filter off','#d55e00','s','-.'),'new':('DVAC new | len <=3','#7b2cbf','D',':'),'attena':('AttenA FK | len <=3','#0072b2','^','-'),'sarm':('SARM k=2 | filter off','#009e73','P',(0,(5,1,1,1))),'prism':('Prism GRPO','#d55e00','D','-'),'grpo':('Clean GRPO','#263238','o','--')}
 plt.rcParams.update({'font.family':'DejaVu Sans','font.size':12,'axes.titlesize':17,'axes.labelsize':12,'legend.fontsize':10.8,'axes.spines.top':False,'axes.spines.right':False})
 outputs={}
 def chart(filename,title,keys,cap,window=1,fixed=False,bc=True):
  fig,ax=plt.subplots(figsize=(14.5,6.7),dpi=140)
  fig.subplots_adjust(left=.066,right=.977,top=.77,bottom=.28 if bc else .23)
  for n,key in enumerate(keys):
   pts=[p for p in DATA['series'][key]['eval/success_once' if fixed else 'env/success_once'] if p['step']<=cap]
   x=[p['step'] for p in pts];y=[p['value']*100 for p in pts]
   if window>1:
    y=[sum(y[i-window+1:i+1])/window for i in range(window-1,len(y))];x=x[window-1:]
   label,color,marker,ls=styles[key]
   label+=f" | R{x[-1]}: {y[-1]:.1f}%"
   ax.plot(x,y,label=label,color=color,marker=marker,linestyle=ls,linewidth=1.45 if window==1 and not fixed else 2.35,alpha=.76 if window==1 and not fixed else .96,markersize=6.5,markerfacecolor='white',markeredgewidth=1.55,markevery=1 if fixed else (n % 5,5))
   ax.plot(x[-1],y[-1],marker=marker,color=color,markersize=8,markerfacecolor=color,markeredgecolor='white',markeredgewidth=.8)
  ax.set_xlim(0,cap);ax.set_ylim(-3,103);ax.yaxis.set_major_locator(MultipleLocator(20));ax.grid(axis='both',alpha=.18)
  ax.set_ylabel('Success rate (%)');ax.set_xlabel('Completed training rounds',labelpad=8)
  ax.xaxis.set_major_locator(MultipleLocator(10 if bc else 20))
  if bc:
   sec=ax.secondary_xaxis('top',functions=(lambda x:x*4,lambda x:x/4));sec.set_xlabel('Cumulative training collection attempts (4 per round)',labelpad=10)
  fig.suptitle(title,x=.066,ha='left',y=.96,fontweight='bold')
  ax.legend(loc='upper center',bbox_to_anchor=(.5,-.19),ncol=2,frameon=False,columnspacing=1.9,handlelength=3.6,labelspacing=.9)
  note='Fixed 32 initial states, evaluated every 5 rounds.' if fixed else ('Trailing full windows only; no padding.' if window>1 else ('4 collection attempts per round; each raw point changes in steps of 25 pp.' if bc else '256 collection attempts per round.'))
  fig.text(.066,.035,note+' Lines stop at actual observations; no extrapolation.',fontsize=10,color='#526475')
  fig.text(.066,.011,'Snapshot: '+DATA['time']+' | Historical clean BC: R100; clean GRPO: R168.',fontsize=9.5,color='#526475')
  b=io.BytesIO();fig.savefig(b,format='png',facecolor='white');plt.close(fig);outputs[filename]=base64.b64encode(b.getvalue()).decode('ascii')
 for i,(suffix,w,fixed,title) in enumerate([('raw',1,False,'collection success'),('ma5',5,False,'collection MA5'),('ma10',10,False,'collection MA10'),('fixed',1,True,'fixed evaluation')],1):
  chart(f'{i:02d}_bc4_all_{suffix}.png','Pi0.5 BC | all five methods | 4/U5 | '+title,['clean','old','new','attena','sarm'],100,window=w,fixed=fixed)
 for i,(suffix,w,fixed,title) in enumerate([('raw',1,False,'collection success'),('ma5',5,False,'collection MA5'),('ma10',10,False,'collection MA10'),('fixed',1,True,'fixed evaluation')],5):
  chart(f'{i:02d}_prism_control_{suffix}.png','Pi0.5 GRPO | Prism vs clean control | '+title,['grpo','prism'],168,window=w,fixed=fixed,bc=False)
 print(json.dumps(outputs))
